	static void Log(uint8 Level, Ferreal::FStr8 Message)
	{
		const FString Text = Ferreal::ToFString(Message);
		switch (Level)
		{
		case 0: UE_LOG(LogFerrealHelloRust, Log, TEXT("%s"), *Text); break;
		case 1: UE_LOG(LogFerrealHelloRust, Warning, TEXT("%s"), *Text); break;
		default: UE_LOG(LogFerrealHelloRust, Error, TEXT("%s"), *Text); break;
		}
	}

