// UGreeter

UGreeter::UGreeter(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer)
{
	Name = TEXT("World");
	Scale = 2.5f;
	bLoud = true;
	Tint = FLinearColor(1.0f, 0.5f, 0.0f, 1.0f);
	Mood = EMood::Excited;
}

void* UGreeter::FerrealState() const
{
	if (!FerrealStatePtr)
	{
		Ferreal::HelloRust::Register();
		FerrealStatePtr = ferreal_HelloRust_Greeter_new(static_cast<UObject*>(const_cast<UGreeter*>(this)));
	}
	return FerrealStatePtr;
}

void UGreeter::BeginDestroy()
{
	if (FerrealStatePtr)
	{
		ferreal_HelloRust_Greeter_drop(FerrealStatePtr);
		FerrealStatePtr = nullptr;
	}
	Super::BeginDestroy();
}

void UGreeter::FerrealChanged(uint32 Index)
{
	if (void* State = FerrealState())
	{
		ferreal_HelloRust_Greeter_m_changed(State, Index);
	}
}

#if WITH_EDITOR
void UGreeter::PostEditChangeProperty(FPropertyChangedEvent& PropertyChangedEvent)
{
	Super::PostEditChangeProperty(PropertyChangedEvent);
	const FName FerrealChangedName = PropertyChangedEvent.GetMemberPropertyName();
	if (FerrealChangedName == GET_MEMBER_NAME_CHECKED(UGreeter, Name))
	{
		FerrealChanged(0);
	}
	else if (FerrealChangedName == GET_MEMBER_NAME_CHECKED(UGreeter, Scale))
	{
		FerrealChanged(1);
	}
	else if (FerrealChangedName == GET_MEMBER_NAME_CHECKED(UGreeter, bLoud))
	{
		FerrealChanged(2);
	}
	else if (FerrealChangedName == GET_MEMBER_NAME_CHECKED(UGreeter, Tint))
	{
		FerrealChanged(3);
	}
	else if (FerrealChangedName == GET_MEMBER_NAME_CHECKED(UGreeter, Mood))
	{
		FerrealChanged(4);
	}
	else if (FerrealChangedName == GET_MEMBER_NAME_CHECKED(UGreeter, Texture))
	{
		FerrealChanged(5);
	}
	else if (FerrealChangedName == GET_MEMBER_NAME_CHECKED(UGreeter, Textures))
	{
		FerrealChanged(6);
	}
}
#endif

void UGreeter::SetName(const FString& InValue)
{
	Name = InValue;
	FerrealChanged(0);
}

void UGreeter::SetLoud(bool InValue)
{
	bLoud = InValue;
	FerrealChanged(2);
}

